/bin/zsh -lc 'npx eslint lib/mediaType.js; echo "LINT_EXIT:$?"
node -e "
var assert = require('"'assert');
var Negotiator = require('./index');
// Acceptance 1
var n = new Negotiator({headers:{}});
assert.strictEqual(n.mediaType(), undefined, 'mediaType() should be undefined');
assert.deepStrictEqual(n.mediaTypes(), [], 'mediaTypes() should be []');
// Acceptance 2
assert.strictEqual(n.mediaType(['text/html','application/json']), 'text/html');
assert.strictEqual(n.mediaType(['application/json','text/html']), 'application/json');
// Regression: explicit */* unchanged
var s = new Negotiator({headers:{accept:'*/*'}});
assert.strictEqual(s.mediaType(), '*/*');
assert.deepStrictEqual(s.mediaTypes(), ['*/*']);
console.log('ALL ACCEPTANCE CHECKS PASS');
\""

